"""new male characters: greetings, follow-ups, shouts, calm (216 clips). Written by the voice director (content), source AssetGen/audio/script/wave_*.txt -> voice_script.json; voice = char_id (VOIX_ARCHITECTURE.md principle 2). Never edit: new content goes to a new batch."""
ITEMS = [
    {'cat': 'greet', 'text': 'Bonsoir. Puis-je vous être utile ?', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Le vestiaire est à gauche, le champagne à droite.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Monsieur le Comte d'Ashcombe vous souhaite une excellente soirée.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Je me permets de vous signaler que votre masque est de travers. Non. Pardon, c'est le mien.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous désirez quelque chose ? Je dispose de tout, sauf de patience.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. La maison vous remercie de ne rien casser.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Le dîner est servi depuis deux heures. Il est donc terminé.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Je suis Barnabé. Je suis toujours là. Toujours.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Je vous prie de ne pas toucher aux tableaux. Ils mordent.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Un parapluie ? Ah non, vous êtes à l'intérieur. Fort bien.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_barnabe_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore moi ? Je veux dire : encore vous ?', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Je vous écoute. Avec résignation.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Si c'est pour les toilettes, deuxième porte, troisième fois que je le dis.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Un coup de feu ! Dans le grand salon ! Inadmissible !', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'On tire ! Je vous prie de vous allonger, mesdames et messieurs !', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': "Le feu ! Veuillez évacuer dans l'ordre, je vous prie !", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Les rideaux de Monsieur ! Ils brûlent !', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Une explosion ! Le service est momentanément interrompu !', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Les plombs ! Un instant, je vais chercher les chandelles !', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_barnabe_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Par ici, je vous prie ! Sans courir... enfin, courez !', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Mesdames et messieurs, gardez votre dignité !', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': 'Bien. Je vais chercher la serpillière.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_barnabe_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Monsieur sera très contrarié.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_barnabe_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Que chacun reprenne sa place. Le buffet reste ouvert.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_barnabe_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Quarante ans de service. Et voilà.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_barnabe_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Je vous prie d'excuser ce contretemps.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_barnabe_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Je n'ai rien vu. C'est mon métier.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_barnabe_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Quelle joie de croiser un visage aimable, même masqué.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Votre masque est un poème. Je suis jaloux.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Ah, bonsoir ! Dans mon palais, on vous aurait accueilli avec des éléphants.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. La nuit est une perle noire, et vous en êtes l'éclat.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Rajan. Prince, mais je ne m'en vante qu'un peu.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Vous êtes la personne la plus intéressante de ce salon. Prouvez-moi que j'ai raison.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. La pluie, ici, ressemble à notre mousson. En plus poli.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Dites-moi, que pensez-vous de ce bal ? Je collectionne les avis.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Un compliment pour un compliment ? Vous commencez.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. J'aime beaucoup votre façon de vous tenir. Royale, presque.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_rajan_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Vous revoilà. Le destin insiste.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore un mot, et je vous nomme conseiller.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Revenir vers un prince, c'est un usage très ancien.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Un coup de feu ! Protégez les dames, vite !', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Il tire ! Mes gardes, où sont mes gardes ?', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Le feu ! Sortez, par ici !', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Les flammes dévorent les tentures !', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Une explosion ! Par tous les dieux !', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': "L'obscurité ! Que personne ne perde son calme !", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_rajan_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Restez près de moi, mes amis !', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': "Courez ! Ce n'est plus l'heure des manières !", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': 'Le calme revient, comme la mer après la mousson.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_rajan_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Mon cœur bat comme un tambour de guerre.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_rajan_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Respirez. Nous sommes vivants, et c'est déjà un festin.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_rajan_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Quelqu'un ici joue un jeu dangereux.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_rajan_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Je vous en prie, reprenez un verre. Je l'offre.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_rajan_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Chez moi, on aurait déjà consulté les astres.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_rajan_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Hé, salut mon pote ! Bonne soirée ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir, bonsoir ! T'as entendu mon orchestre ? Ça swingue, hein ?", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Hey ! Toi, t'as le rythme dans la démarche, ça se voit.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir ! Sonny, chef d'orchestre. Tu danses ou tu regardes ?", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Salut ! T'as pas vu mon trompettiste ? Il s'est perdu au bar.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir, ma belle tête masquée ! Ça roule ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Hé, bonsoir ! Ce soir c'est jazz, champagne et tempête. Le paradis.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Salut, mon pote ! Souris, c'est une fête, man !", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir ! Tu veux une chanson ? C'est la maison qui paie.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Hé ! Toi, je t'ai vu taper du pied pendant le morceau. Bravo.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_sonny_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Encore toi ? T'es mon fan numéro un, c'est ça ?", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Qu'est-ce qu'il y a, mon pote ? Une demande spéciale ?", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Hé, doucement, je fais une pause entre deux morceaux.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Hé, ils tirent ! Tout le monde à terre, baby !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': "Un coup de feu ! C'est pas le batteur, ça !", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Au feu ! Sauvez les instruments !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Ça brûle, man ! Sortez, sortez !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Boum ! C'était pas dans la partition, ça !", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Hé, qui a éteint ? On joue dans le noir maintenant ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_sonny_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Courez, courez, en rythme si possible !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': "Oh là là, c'est la panique ! Par ici, les amis !", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': 'Bon. Le spectacle continue, pas vrai ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_sonny_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "J'ai les mains qui tremblent. Pas idéal pour un musicien.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_sonny_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Respire, mon pote. Un, deux, trois, souffle.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_sonny_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "J'ai vu des bagarres à Harlem, mais là...", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_sonny_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Allez, l'orchestre ! On reprend, doucement.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_sonny_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Ce bal, c'est du blues, maintenant.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_sonny_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Ah ! Bonsoir. Vous ne seriez pas égyptologue, par hasard ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir, bonsoir. Où en étais-je ? Ah oui : bonsoir.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Votre masque me rappelle une momie de la dix-huitième dynastie. C'est un compliment.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Oh, bonsoir ! Vous avez vu mes lunettes ? Ah, elles sont sur mon nez.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Saviez-vous que les pharaons donnaient aussi des bals masqués ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Professeur Ambroise. Enfin, je crois. Oui, c'est bien moi.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir ! Quelle soirée ! Presque aussi passionnante qu'un tombeau.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Excusez-moi, je pensais à Toutânkhamon. Je pense souvent à lui.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Ah, bonsoir. Vous avez l'air de quelqu'un qui aime les vieilles pierres.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Je cherche la bibliothèque. Ou la sortie. Peu importe.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_ambroise_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Vous revoilà ! Où en étions-nous ? Les hiéroglyphes ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Encore vous ? Ou vous êtes quelqu'un d'autre ? Ces masques...", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Ah ! J'allais justement vous raconter Karnak.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'On tire ! Comme à Louxor, en vingt-trois !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Un coup de feu ! Mes lunettes, je ne vois plus rien !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Au feu ! Sauvez les manuscrits !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Le feu ! Comme à la bibliothèque d'Alexandrie !", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Une explosion ! Une explosion de dynamite, je reconnais l'odeur !", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Le noir ! Comme dans une pyramide !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_ambroise_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Fuyez ! Fuyez, la malédiction !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Au secours ! Euh... où est la sortie ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': 'Bon. Où en étais-je, avant tout ça ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_ambroise_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "J'ai vu des tombeaux moins effrayants.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_ambroise_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Fascinant. Terrifiant, mais fascinant.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_ambroise_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "C'est la malédiction, j'en suis sûr. Ou pas.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_ambroise_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Un petit verre pour le cœur, si vous permettez.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_ambroise_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Je prendrai des notes. Plus tard. Quand mes mains arrêteront de trembler.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_ambroise_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Oh ! Bonsoir. Pardon, je bouchais le passage ?', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Excusez-moi, je suis juste le chauffeur.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir ! Euh... vous cherchez votre voiture ? Elle est au garage, au sec.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. C'est la première fois que je vois autant de beau monde.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Pardon si je parle mal, je suis plus doué avec les moteurs.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Ah, bonsoir ! Je peux vous aider à quelque chose ?', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. On m'a dit de pas parler aux invités. Mais bon, bonsoir.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous avez une belle allure. Comme une Hispano-Suiza.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir ! Excusez, j'ai encore un peu de cambouis sur les gants.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Il fait un temps à pas mettre une Bugatti dehors.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_lucien_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Oui ? Pardon, je vous ai pas entendu revenir.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore vous ? Je fais quelque chose de travers ?', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Je peux vous chercher quelque chose ? Un verre ? Une voiture ?', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Ils tirent ! Baissez-vous, pardon, baissez-vous !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Un coup de feu ! Oh mon Dieu, oh mon Dieu !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Au feu ! Il faut sortir les voitures du garage !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Ça brûle ! Pardon, laissez passer !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Une explosion ! C'est pas un réservoir, au moins ?", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': "La lumière ! J'ai une lampe dans la voiture !", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_lucien_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Excusez-moi ! Pardon ! Sauvez-vous !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Par ici, la sortie de service, par ici !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': "Pardon. J'ai crié comme une fillette.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_lucien_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Je voulais juste conduire, moi.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_lucien_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Ça va, tout le monde ? Je peux aider ?', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_lucien_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Mon patron va me renvoyer, c'est sûr.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_lucien_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Je vais chercher de l'eau. Pour les dames. Et pour moi.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_lucien_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "J'ai les jambes en guimauve.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_lucien_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir, mon ami. On est entre gens raisonnables, hein ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Hé, bonsoir. Tony. Tony les Gants. Tu as entendu parler de moi ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Belle soirée. Ce serait dommage qu'il arrive quelque chose.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir, bonsoir. Tu as l'air d'une personne qui sait garder un secret.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Hé. Bonsoir. Souris, je te veux du bien. Pour l'instant.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Joli masque. Moi, je garde mes gants. Toujours.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir, mon ami. Tu me dois rien ? Bon. Tant mieux pour toi.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Ah, bonsoir. On se serre la main ? Doucement, hein.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Chez moi, à Brooklyn, on dirait : quelle classe.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Tu connais Victor ? Dis-lui que Tony le cherche. Gentiment.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tony_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore toi ? Tu veux faire affaire, capisce ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Tu reviens ? Bon. J'aime les gens fidèles.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Écoute, mon ami. Une fois, c'est poli. Trois fois, c'est suspect.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': "Qui a tiré ? C'est pas moi, cette fois !", 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Hé ! Qui ose tirer sans me demander ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Le feu ! Sortez, sortez, vite !', 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Ça brûle ! Mes gants ! Pas mes gants !', 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Une bombe ! C'est pas mon style, ça !", 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': "La lumière ! Quelqu'un touche ma poche, il est mort !", 'voice': 'char_tony', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_tony_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Dégagez ! Tony passe !', 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Hé ! Tout le monde dehors, et vite !', 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': "Bon. Personne a rien vu. On est d'accord ?", 'voice': 'char_tony', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tony_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Ça, c'est pas du travail de professionnel.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_tony_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Allez, on se calme. Tony offre la tournée.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tony_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Si je trouve celui qui a fait ça, on va discuter.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_tony_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "C'est rien. À Chicago, c'est un mardi soir.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tony_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Mes gants sont pleins de poussière. Ça me met en colère.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_tony_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Howdy ! Bonsoir, l'ami ! Tex Callahan, du Texas !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir ! Au Texas, on se serre la main plus fort que ça !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Hé, bonsoir ! Joli masque. Chez moi, ils sont deux fois plus grands.', 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir, bonsoir ! Vous buvez quoi ? C'est moi qui paie, comme toujours !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Howdy ! Grande maison, hein ? Mon garage est plus grand.', 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir ! Vous connaissez le Texas ? Non ? Quel dommage !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Ha ! Bonsoir ! Tapez-m'en cinq, comme on dit !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir, l'ami ! Vous avez une tête à aimer le pétrole !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir ! Cette tempête ? Au Texas, on appelle ça une brise !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Howdy, howdy ! Vous dansez la gigue ? Moi, oui !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_tex_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Encore vous ? Ha ! Vous m'aimez bien, hein ?", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Hé, l'ami ! Toujours là ? Au Texas, on se serait déjà mariés !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Vous voulez des actions dans mon puits ? Ha ha !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Hé ! Qui tire ? Au Texas, on prévient avant !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Un coup de feu ! Tout le monde derrière moi !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Au feu ! Ça me rappelle mon puits numéro six !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Ça brûle ! Sortez, les amis, sortez !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Boum ! Ça, c'était de la dynamite texane !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': "Qui a éteint ? Au Texas, on a l'électricité !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_tex_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Yee-haw ! Tout le monde dehors !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': "Poussez-vous, je suis large d'épaules !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': "Ha ! Au Texas, c'est un samedi soir ordinaire.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tex_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Bon, celle-là, je l'avoue, elle m'a fait peur.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_tex_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Tournée générale ! C'est Tex qui paie !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tex_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Ma femme va me dire : je te l'avais dit.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_tex_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Allez, les amis, on se remet ! C'est fini !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tex_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "J'ai perdu mon chapeau. Mon chapeau, nom d'un chien.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_tex_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Capitaine Morel. Bienvenue à bord. Enfin, à terre.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Belle mer ce soir. Je plaisante, c'est une tempête de force huit.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Gardez le pied marin, le parquet tangue.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Vous avez déjà traversé l'Atlantique ? On en parlera.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir, matelot. Pardon, l'habitude.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Ne vous inquiétez pas pour la tempête. J'en ai vu d'autres.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Le grand mât de ce manoir, c'est l'escalier. Tenez la rampe.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Une nuit comme celle-ci, on la raconte pendant vingt ans.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Le vent tourne à l'ouest. Ça promet.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Calme et bonne humeur, c'est la règle à bord.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_morel_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore là ? Bien. Un bon équipage reste groupé.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Vous voulez une histoire de mer ? J'en ai une par nœud.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Paré à vous écouter.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Coup de feu ! Tout le monde à couvert, immédiatement !', 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Un tireur ! Baissez-vous et ne bougez plus !', 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Feu à bord ! Euh, au manoir ! Évacuez !', 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Incendie ! Formez une chaîne, de l'eau, vite !", 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Explosion ! Personne ne panique, on évacue dans l'ordre !", 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Panne générale ! Restez où vous êtes !', 'voice': 'char_morel', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_morel_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': "Les femmes et les enfants d'abord ! Et vite !", 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Vers les canots ! Euh, vers les portes ! Vite !', 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': 'Le danger est passé. Comptons-nous.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_morel_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Quarante ans de mer, et jamais vu ça sur terre.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_morel_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Tout le monde va bien ? Bon. Respirez profondément.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_morel_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Gardez votre sang-froid. Les autres vous regardent.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_morel_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Un remontant pour ceux qui tremblent. C'est l'usage.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_morel_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "La tempête n'est pas que dehors, ce soir.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_morel_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
]
